INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 35, 'theory', 'Quiz: tokio — channels and synchronization');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 0, 'What does rx.recv().await return when all Senders are dropped and the channel is empty?', '["Err", "None", "A panic", "Waits forever"]', 1, 'A closed and drained mpsc channel returns None — this is how the receive loop ends by itself.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 1, 'What happens to send().await in a bounded channel when the buffer is full?', '["The message is lost", "The task waits until there is room", "An error is returned", "The buffer doubles"]', 1, 'send waits: this is how a slow consumer slows down the producer — backpressure. try_send, instead of waiting, returns an error right away.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 2, 'What is oneshot good for in the request-reply pattern?', '["Broadcasting to all subscribers", "The oneshot sender is put into the message, and the worker task replies through it", "Limiting the number of tasks", "Storing the latest value"]', 1, 'oneshot carries exactly one value: ideal for a reply to a specific request.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 3, 'How does tokio::sync::Mutex differ from std::sync::Mutex?', '["It doesn''t", "Its guard can be held across .await, and lock() is async", "It is faster for short sections", "It doesn''t need Arc"]', 1, 'A std mutex guard can''t be held across .await in a spawned task (it is not Send). The tokio one can, but it is slower.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 35, 4, 'What does Semaphore::new(3) do?', '["Creates three threads", "Allows no more than three permit holders at once", "Creates a channel for three messages", "Starts three tasks"]', 1, 'A semaphore holds a number of permits: acquire waits for a free one, and while the guard is alive the permit is taken.');
